from pathlib import Path
import re
import sys
from typing import Iterable


_HEADER_RE = re.compile(r"^\[([A-Za-z_][A-Za-z0-9_-]*)\]$")
_DIALOGUE_RE = re.compile(
    r"^([^:]+):\s*(.*?)\s*->\s*([A-Za-z_][A-Za-z0-9_-]*)$"
)
_CHOICE_RE = re.compile(
    r"^(\d+)\.\s*(.*?)\s*->\s*([A-Za-z_][A-Za-z0-9_-]*)$"
)


@dataclass(frozen=True)
class _SectionLine:
    line_number: int
    text: str


@dataclass(frozen=True)
class _Section:
    identifier: str
    lines: tuple[_SectionLine, ...]


def _parse_sections(text: str) -> list[_Section]:
    sections: list[_Section] = []
    section_ids: set[str] = set()
    current_identifier: str | None = None
    current_lines: list[_SectionLine] = []

    def finish_section() -> None:
        nonlocal current_identifier, current_lines
        if current_identifier is not None:
            sections.append(_Section(current_identifier, tuple(current_lines)))
        current_identifier = None
        current_lines = []

    for line_number, physical_line in enumerate(text.splitlines(), start=1):
        line = physical_line.strip()
        if not line:
            continue

        header_match = _HEADER_RE.fullmatch(line)
        if header_match:
            finish_section()
            identifier = header_match.group(1)
            if identifier in section_ids:
                raise ValueError(
                    f"Duplicate section identifier '{identifier}' on line {line_number}"
                )
            section_ids.add(identifier)
            current_identifier = identifier
            continue

        if line.startswith("[") or line.endswith("]"):
            raise ValueError(f"Invalid header on line {line_number}: {line!r}")
        if current_identifier is None:
            raise ValueError(f"Content before the first section on line {line_number}")
        current_lines.append(_SectionLine(line_number, line))

    finish_section()
    if not sections:
        raise ValueError("Script contains no sections")
    return sections


def _normalize_sections(
    sections: Iterable[_Section],
) -> list[tuple[str, list[dict[str, str]]]]:
    normalized: list[tuple[str, list[dict[str, str]]]] = []

    for section in sections:
        if not section.lines:
            raise ValueError(f"Section '{section.identifier}' is empty")

        section_kind: str | None = None
        parsed_lines: list[dict[str, str]] = []
        choice_numbers: set[int] = set()

        for section_line in section.lines:
            dialogue_match = _DIALOGUE_RE.fullmatch(section_line.text)
            choice_match = _CHOICE_RE.fullmatch(section_line.text)

            if dialogue_match:
                line_kind = "dialogue"
                parsed_line = {
                    "speaker": dialogue_match.group(1).strip(),
                    "text": dialogue_match.group(2).strip(),
                    "target": dialogue_match.group(3),
                }
            elif choice_match:
                line_kind = "choice"
                choice_number_text = choice_match.group(1)
                choice_number = int(choice_number_text)
                if choice_number in choice_numbers:
                    raise ValueError(
                        f"Duplicate choice number {choice_number} in section '
                        f"{section.identifier}' on line {section_line.line_number}"
                    )
                choice_numbers.add(choice_number)
                parsed_line = {
                    "number": choice_number_text,
                    "text": choice_match.group(2).strip(),
                    "target": choice_match.group(3),
                }
            else:
                raise ValueError(
                    f"Malformed line {section_line.line_number} in section '
                    f"{section.identifier}': {section_line.text!r}"
                )

            if section_kind is not None and section_kind != line_kind:
                raise ValueError(
                    f"Section '{section.identifier}' mixes dialogue and choice lines "
                    f"(line {section_line.line_number})"
                )
            section_kind = line_kind
            parsed_lines.append(parsed_line)

        normalized.append((section.identifier, parsed_lines))

    return normalized


def _build_graph(
    sections: list[tuple[str, list[dict[str, str]]]],
) -> dict[str, list[dict[str, str]]]:
    nodes: list[dict[str, str]] = []
    edges: list[dict[str, str]] = []
    declared_node_ids: set[str] = set()

    for section_identifier, lines in sections:
        if lines[0].get("speaker") is not None:
            for line_number, line in enumerate(lines, start=1):
                node_id = (
                    section_identifier
                    if line_number == 1
                    else f"{section_identifier}#line{line_number}"
                )
                if node_id in declared_node_ids:
                    raise ValueError(f"Duplicate node id '{node_id}'")
                declared_node_ids.add(node_id)
                nodes.append(
                    {
                        "id": node_id,
                        "text": line["text"],
                        "speaker": line["speaker"],
                        "type": "line",
                    }
                )
                edges.append({"from": node_id, "to": line["target"], "text": ""})
        else:
            if section_identifier in declared_node_ids:
                raise ValueError(f"Duplicate node id '{section_identifier}'")
            declared_node_ids.add(section_identifier)
            nodes.append(
                {
                    "id": section_identifier,
                    "text": "",
                    "speaker": "",
                    "type": "choice",
                }
            )
            for line in lines:
                visible_choice = f"{line['number']}. {line['text']}"
                edges.append(
                    {
                        "from": section_identifier,
                        "to": line["target"],
                        "text": visible_choice,
                    }
                )

    end_referenced = False
    for edge in edges:
        target = edge["to"]
        if target == "End":
            end_referenced = True
        elif target not in declared_node_ids:
            raise ValueError(
                f"Edge from '{edge['from']}' targets undeclared node '{target}'"
            )

    if end_referenced:
        if "End" in declared_node_ids:
            raise ValueError("Section 'End' conflicts with the reserved terminal node")
        nodes.append({"id": "End", "text": "", "speaker": "", "type": "terminal"})

    _validate_graph(nodes, edges)
    return {"nodes": nodes, "edges": edges}


def _validate_graph(nodes: list[dict[str, str]], edges: list[dict[str, str]]) -> None:
    required_node_keys = {"id", "text", "speaker", "type"}
    required_edge_keys = {"from", "to", "text"}
    node_ids = [node["id"] for node in nodes]
    node_id_set = set(node_ids)

    if not nodes:
        raise ValueError("Graph contains no entry node")
    if len(node_ids) != len(node_id_set):
        raise ValueError("Graph contains duplicate node ids")
    if any(set(node) != required_node_keys for node in nodes):
        raise ValueError("Graph contains a node with an invalid key set")
    if any(set(edge) != required_edge_keys for edge in edges):
        raise ValueError("Graph contains an edge with an invalid key set")

    adjacency: dict[str, list[str]] = {node_id: [] for node_id in node_ids}
    for edge in edges:
        source = edge["from"]
        target = edge["to"]
        if source not in node_id_set:
            raise ValueError(f"Edge source '{source}' is undeclared")
        if target not in node_id_set:
            raise ValueError(f"Edge target '{target}' is undeclared")
        adjacency[source].append(target)

    entry_id = node_ids[0]
    reachable: set[str] = set()
    pending = deque([entry_id])
    while pending:
        node_id = pending.popleft()
        if node_id in reachable:
            continue
        reachable.add(node_id)
        pending.extend(adjacency[node_id])

    if entry_id not in reachable:
        raise ValueError(f"Entry node '{entry_id}' is unreachable")
    unreachable = [node_id for node_id in node_ids if node_id not in reachable]
    if unreachable:
        raise ValueError(
            "Unreachable node(s) from entry "
            f"'{entry_id}': {', '.join(unreachable)}"
        )


def _dot_escape(value: str) -> str:
    return (
        value.replace("\\", "\\\\")
        .replace('"', '\\"')
        .replace("\r", "\\r")
        .replace("\n", "\\n")
    )


def graph_to_dot(graph: dict[str, list[dict[str, str]]]) -> str:
    """Return a deterministic DOT representation of a normalized graph."""
    lines = ["digraph dialogue {"]
    for node in graph["nodes"]:
        if node["type"] == "line":
            label = f"{node['speaker']}: {node['text']}"
            shape = "box"
        elif node["type"] == "choice":
            label = node["id"]
            shape = "diamond"
        else:
            label = node["id"]
            shape = "oval"
        lines.append(
            f'  "{_dot_escape(node["id"])}" '
            f'[label="{_dot_escape(label)}", shape="{shape}"];'
        )

    for edge in graph["edges"]:
        lines.append(
            f'  "{_dot_escape(edge["from"])}" -> '
            f'"{_dot_escape(edge["to"])}" '
            f'[label="{_dot_escape(edge["text"])}"];'
        )
    lines.append("}")
    return "\n".join(lines) + "\n"


def parse_script(text: str) -> dict[str, list[dict[str, str]]]:
    """Parse and validate a dialogue script into ordered node and edge dictionaries."""
    sections = _parse_sections(text)
    normalized_sections = _normalize_sections(sections)
    return _build_graph(normalized_sections)


def main() -> int:
    script_path = Path("/app/script.txt")
    json_path = Path("/app/dialogue.json")
    dot_path = Path("/app/dialogue.dot")

    try:
        graph = parse_script(script_path.read_text(encoding="utf-8"))
        json_text = json.dumps(graph, ensure_ascii=False, indent=2) + "\n"
        dot_text = graph_to_dot(graph)
        json_path.write_text(json_text, encoding="utf-8")
        dot_path.write_text(dot_text, encoding="utf-8")
    except (OSError, UnicodeError, ValueError) as error:
        print(f"Error: {error}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
