    if len(node_ids) != len(node_id_set):
        raise ValueError("Graph contains duplicate node ids")
    if any(set(node) != required_node_keys for node in nodes):
        raise ValueError("Graph contains a node with an invalid key set")
    if any(set(edge) != required_edge_keys for edge in edges):
        raise ValueError("Graph contains an edge with an invalid key set")

    adjacency: dict[str, list[str]] = {node_id: [] for node_id in node_ids}
    for edge in edges:
        source = edge["from"]
        target = edge["to"]
        if source not in node_id_set:
            raise ValueError(f"Edge source '{source}' is undeclared")
        if target not in node_id_set:
            raise ValueError(f"Edge target '{target}' is undeclared")
        adjacency[source].append(target)

