    """Return a deterministic DOT representation of a normalized graph."""
    lines = ["digraph dialogue {"]
    for node in graph["nodes"]:
        if node["type"] == "line":
            label = f"{node['speaker']}: {node['text']}"
            shape = "box"
        elif node["type"] == "choice":
            label = node["id"]
            shape = "diamond"
        else:
            label = node["id"]
            shape = "oval"
        lines.append(
            f'  "{_dot_escape(node["id"])}" '
            f'[label="{_dot_escape(label)}", shape="{shape}"];'
        )

    for edge in graph["edges"]:
        lines.append(
            f'  "{_dot_escape(edge["from"])}" -> '
            f'"{_dot_escape(edge["to"])}" '
            f'[label="{_dot_escape(edge["text"])}"];'
